contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log, bool initializeFirst) public {
        require(initializeFirst || !initializeFirst);
        bool revertedBeforeInit;
        bool revertedAfterInit;

        c.Initialized(); if (__ESBMC_reverted()) return;

        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedAfterInit = true; } else { revertedAfterInit = false; }

        assert(revertedAfterInit);
    }

    receive() external payable {}
}

